def affected(nums) -> bool:
    if any(x < 0 or 0 <= x <= 9 for x in nums):
        return True
    s = [str(x) for x in nums]
    f = [sum(map(int, t)) for t in s]
    g = [-int(t[1]) + sum(map(int, t[2:])) for t in s]
    n = len(nums)
    return sorted(range(n), key=lambda i: f[i]) != sorted(range(n), key=lambda i: g[i])
